service.method:

        INSERT 
          INTO SCTGL (
               HOUSE_CODE
             , COMPANY_CODE
             , CONT_NO
             , CONT_GL_SEQ
             , ADD_DATE
             , ADD_TIME
             , ADD_USER_ID
             , CHANGE_DATE
             , CHANGE_TIME
             , CHANGE_USER_ID
             , CONT_TYPE
             , CONT_SUBJECT  
             , DEL_FLAG
             , STATUS  
             , CATEGORY
             , CREATOR
             , CONT_METHOD
             , CONT_FORM_NO
             , CONT_DATE
             , CONT_FROM
             , CONT_TO
             , EXPIRED_ALARM
             , SUMMARY
             , PRE_CONT_NUMBER
             , GL_SEQ_REASON
             , CONT_AMT
             , SIGN_ORDER
             , DATA_SOURCE
             , PUSH_SEND_DATE
             , ROW_NUM
             , CREATOR_DEPT
            ) 
      VALUES (
               ${session.HOUSE_CODE}
             , ${session.COMPANY_CODE}
             , ${CONT_NO}
             , ${CONT_GL_SEQ}
             , ${current.DATE}
             , ${current.TIME}
             , ${session.ID}
             , ${current.DATE}
             , ${current.TIME}
             , ${session.ID}
             , ${CONT_TYPE}
             , ${CONT_SUBJECT}
             , 'N'
             , 'T'
             , ${CATEGORY}
             , ${session.ID}
             , ${CONT_METHOD}
             , ${CONT_FORM_NO}
             , ${CONT_DATE}
             , ${CONT_FROM}
             , ${CONT_TO}
             , ${EXPIRED_ALARM}
             , ${SUMMARY}
             , ${PRE_CONT_NUMBER}
             , ${GL_SEQ_REASON}
             , ${CONT_AMT}
             , ${SIGN_ORDER}
             , ${DATA_SOURCE}
             , ${PUSH_SEND_DATE}
             ,	(
					SELECT
						TO_CHAR(MAX(TO_NUMBER(ROW_NUM)) + 1)
					FROM SCTGL
					WHERE
						HOUSE_CODE = ${session.HOUSE_CODE}
						AND COMPANY_CODE = ${session.COMPANY_CODE}
				) 
			  , ${session.DEPARTMENT}
         )


DELETE
  FROM SCTGL
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND CONT_NO      = ${CONT_NO}               
   AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


SELECT ITEM_CODE
     , ITEM_VALUE
  FROM SCTMD
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND CONT_NO      = ${CONT_NO}
   AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


INSERT 
  INTO SCTMD
     ( HOUSE_CODE
     , COMPANY_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , ITEM_CODE
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , ITEM_VALUE
  )
VALUES 
     ( ${session.HOUSE_CODE}
     , ${COMPANY_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , ${ITEM_CODE}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${ITEM_VALUE}
  )


DELETE
  FROM SCTMD
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND CONT_NO      = ${CONT_NO}
   AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


INSERT
  INTO SSIGN
     ( HOUSE_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , SIGNER_NO
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , SEQ
     , SIGNER_ID
     , SIGNER_NAME
     , SIGNER_EMAIL
     , SIGNER_PHONE
     , SIGNER_COMPANY_CODE
     , SIGNER_COMPANY_NAME
     , SIGNER_COMPANY_OWNER
     , SIGNER_COMPANY_ADDR
     , DEL_FLAG
     , SIGN_FLAG
     , SIGN_TYPE
     , SIGN_KEY
     , SIGN_VALUE
     , SIGN_ORG_VALUE
     , CERT_INFO
     , SIGN_COMMENT
     , SIGN_FIX_HTML
     , LINK
     )
VALUES
     ( ${session.HOUSE_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , ${SIGNER_NO}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${SEQ}
     , ${SIGNER_ID}
     , ${SIGNER_NAME}
     , ${SIGNER_EMAIL}
     , ${SIGNER_PHONE}
     , ${SIGNER_COMPANY_CODE}
     , ${SIGNER_COMPANY_NAME}
     , ${SIGNER_COMPANY_OWNER}
     , ${SIGNER_COMPANY_ADDR}
     , 'N'
     , 'W'
     , ${SIGN_TYPE}
     , ${SIGN_KEY}
     , ${SIGN_VALUE}
     , ${SIGN_ORG_VALUE}
     , ${CERT_INFO}
     , ${SIGN_COMMENT}
     , ${SIGN_FIX_HTML}
     , ${LINK}
     )


UPDATE SSIGN
   SET CHANGE_DATE          = ${current.DATE}
     , CHANGE_TIME          = ${current.TIME}
     , CHANGE_USER_ID       = ${session.ID}
     , SEQ                  = #DB_OWNER#nvl(${SEQ}                 , SEQ)
     , SIGNER_ID            = #DB_OWNER#nvl(${SIGNER_ID}           , SIGNER_ID)
     , SIGNER_NAME          = #DB_OWNER#nvl(${SIGNER_NAME}         , SIGNER_NAME)
     , SIGNER_EMAIL         = #DB_OWNER#nvl(${SIGNER_EMAIL}        , SIGNER_EMAIL)
     , SIGNER_PHONE         = #DB_OWNER#nvl(${SIGNER_PHONE}        , SIGNER_PHONE)
     , SIGNER_COMPANY_CODE  = #DB_OWNER#nvl(${SIGNER_COMPANY_CODE} , SIGNER_COMPANY_CODE)
     , SIGNER_COMPANY_NAME  = #DB_OWNER#nvl(${SIGNER_COMPANY_NAME} , SIGNER_COMPANY_NAME)
     , SIGNER_COMPANY_OWNER = #DB_OWNER#nvl(${SIGNER_COMPANY_OWNER}, SIGNER_COMPANY_OWNER)
     , SIGNER_COMPANY_ADDR  = #DB_OWNER#nvl(${SIGNER_COMPANY_ADDR} , SIGNER_COMPANY_ADDR)
     , SIGN_FLAG            = #DB_OWNER#nvl(${SIGN_FLAG}           , SIGN_FLAG)
     , SIGN_TYPE            = #DB_OWNER#nvl(${SIGN_TYPE}           , SIGN_TYPE)
     , SIGN_KEY             = #DB_OWNER#nvl(${SIGN_KEY}            , SIGN_KEY)
     , SIGN_VALUE           = #DB_OWNER#nvl(${SIGN_VALUE}          , SIGN_VALUE)
     , SIGN_ORG_VALUE       = #DB_OWNER#nvl(${SIGN_ORG_VALUE}      , SIGN_ORG_VALUE)
     , CERT_INFO            = #DB_OWNER#nvl(${CERT_INFO}           , CERT_INFO)
     , SIGN_COMMENT         = #DB_OWNER#nvl(${SIGN_COMMENT}        , SIGN_COMMENT)
     , SIGN_FIX_HTML        = 
     	TO_CLOB
     	((
     		SELECT SIGN_FIX_HTML 
     		FROM SSIGN 
     		WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
     		AND CONT_NO = ${CONT_NO} 
     		AND CONT_GL_SEQ = ${CONT_GL_SEQ} 
     		AND SIGNER_NO = ${SIGNER_NO}
     	)) || TO_CLOB(${SIGN_FIX_HTML})
     , LINK                 = #DB_OWNER#nvl(${LINK}                , LINK)
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
   AND SIGNER_NO   = ${SIGNER_NO}


DELETE
  FROM SSIGN
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}


SELECT COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,#DB_OWNER#GETCOMPANYNAME(${session.HOUSE_CODE},
                                ${session.COMPANY_CODE},
                                ${session.LANGUAGE}
       ) AS USER_COMPANY_NAME
      ,USER_ID          
      ,#DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, 
                             ${session.COMPANY_CODE}, USER_ID, 
                             ${session.LANGUAGE}
       ) AS USER_NAME
      ,ACTION           
      ,IP
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND CONT_NO      = ${CONT_NO}
   AND CONT_GL_SEQ  = ${CONT_GL_SEQ}
 ORDER
    BY SEQ


INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${COMPANY_CODE}     
      ,${CONT_NO}          
      ,${CONT_GL_SEQ}      
      ,(SELECT COUNT(*) + 1
          FROM SPMGT InPMGT
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${CONT_NO}
           AND InPMGT.CONT_GL_SEQ  = ${CONT_GL_SEQ}
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${session.ID}
      ,${ACTION}           
      ,${IP}
     )


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND CONT_NO      = ${CONT_NO}
   AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


SELECT SIGNER_NO
      ,SEQ
      ,SIGNER_ID
      ,SIGNER_NAME
      ,SIGNER_EMAIL
      ,SIGNER_PHONE
      ,SIGNER_COMPANY_CODE
      ,SIGNER_COMPANY_NAME
      ,SIGNER_COMPANY_OWNER
      ,SIGNER_COMPANY_ADDR
      ,TERMINATION_STATUS
  FROM SCTDS
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
   AND TERMINATION_STATUS  = $S{TERMINATION_STATUS}
   AND SIGNER_ID           = $S{SIGNER_ID}
   AND SIGNER_COMPNAY_CODE = $S{SIGNER_COMPNAY_CODE}
 ORDER 
    BY SEQ


 INSERT
   INTO SCTDS 
      ( HOUSE_CODE
       ,CONT_NO
       ,CONT_GL_SEQ
       ,SIGNER_NO
       ,ADD_DATE
       ,ADD_TIME
       ,ADD_USER_ID
       ,CHANGE_DATE
       ,CHANGE_TIME
       ,CHANGE_USER_ID
       ,SEQ
       ,SIGNER_ID
       ,SIGNER_NAME
       ,SIGNER_EMAIL
       ,SIGNER_PHONE
       ,SIGNER_COMPANY_CODE
       ,SIGNER_COMPANY_NAME
       ,SIGNER_COMPANY_OWNER
       ,SIGNER_COMPANY_ADDR
       ,TERMINATION_STATUS
       ,LINK
       ,SIGN_COMMENT
      )
VALUES( ${session.HOUSE_CODE}
       ,${CONT_NO}
       ,${CONT_GL_SEQ}
       ,${SIGNER_NO}
       ,${current.DATE}
       ,${current.TIME}
       ,${session.ID}
       ,${current.DATE}
       ,${current.TIME}
       ,${session.ID}
       ,${SEQ}
       ,${SIGNER_ID}
       ,${SIGNER_NAME}
       ,${SIGNER_EMAIL}
       ,${SIGNER_PHONE}
       ,${SIGNER_COMPANY_CODE}
       ,${SIGNER_COMPANY_NAME}
       ,${SIGNER_COMPANY_OWNER}
       ,${SIGNER_COMPANY_ADDR}
       ,${TERMINATION_STATUS}
       ,${LINK}
       ,${SIGN_COMMENT}
      )


UPDATE SCTDS
   SET CHANGE_DATE          = ${current.DATE}      
     , CHANGE_TIME          = ${current.TIME}      
     , CHANGE_USER_ID       = ${session.ID}
     , SEQ                  = #DB_OWNER#nvl(${SEQ}                 , SEQ)                 
     , SIGNER_ID            = #DB_OWNER#nvl(${SIGNER_ID}           , SIGNER_ID)              
     , SIGNER_NAME          = #DB_OWNER#nvl(${SIGNER_NAME}         , SIGNER_NAME)         
     , SIGNER_EMAIL         = #DB_OWNER#nvl(${SIGNER_EMAIL}        , SIGNER_EMAIL)        
     , SIGNER_PHONE         = #DB_OWNER#nvl(${SIGNER_PHONE}        , SIGNER_PHONE)       
     , SIGNER_COMPANY_CODE  = #DB_OWNER#nvl(${SIGNER_COMPANY_CODE} , SIGNER_COMPANY_CODE) 
     , SIGNER_COMPANY_NAME  = #DB_OWNER#nvl(${SIGNER_COMPANY_NAME} , SIGNER_COMPANY_NAME)
     , SIGNER_COMPANY_OWNER = #DB_OWNER#nvl(${SIGNER_COMPANY_OWNER}, SIGNER_COMPANY_OWNER)
     , SIGNER_COMPANY_ADDR  = #DB_OWNER#nvl(${SIGNER_COMPANY_ADDR} , SIGNER_COMPANY_ADDR)
     , TERMINATION_STATUS   = #DB_OWNER#nvl(${TERMINATION_STATUS}  , TERMINATION_STATUS)
     , SIGN_COMMENT         = #DB_OWNER#nvl(${SIGN_COMMENT}        , SIGN_COMMENT)
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
   AND SIGNER_NO   = ${SIGNER_NO}


DELETE
  FROM SCTDS
 WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
   AND SIGNER_NO   = ${SIGNER_NO}


INSERT
  INTO SCTRV
     ( HOUSE_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , SEQ
     , REVIEWER_NO
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , REVIEW_SEQ
     , REVIEWER_ID
     , REVIEWER_NAME
     , REVIEWER_EMAIL
     , REVIEWER_PHONE
     , REVIEWER_COMPANY_CODE
     , REVIEWER_COMPANY_NAME
     , REVIEWER_COMPANY_OWNER
     , REVIEWER_COMPANY_ADDR
     , DEL_FLAG
     , REVIEW_FLAG
     , REVIEW_COMMENT
     , LINK
     )
VALUES
     ( ${session.HOUSE_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , ${SEQ}
     , ${REVIEWER_NO}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${REVIEW_SEQ}
     , ${REVIEWER_ID}
     , ${REVIEWER_NAME}
     , ${REVIEWER_EMAIL}
     , ${REVIEWER_PHONE}
     , ${REVIEWER_COMPANY_CODE}
     , ${REVIEWER_COMPANY_NAME}
     , ${REVIEWER_COMPANY_OWNER}
     , ${REVIEWER_COMPANY_ADDR}
     , 'N'
     , 'RW'
     , ${REVIEW_COMMENT}
     , ${LINK}
     )


UPDATE SCTRV
   SET CHANGE_DATE            = ${current.DATE}
     , CHANGE_TIME            = ${current.TIME}
     , CHANGE_USER_ID         = ${session.ID}
     , REVIEW_SEQ             = #DB_OWNER#nvl(${REVIEW_SEQ}            , REVIEW_SEQ)
     , REVIEWER_ID            = #DB_OWNER#nvl(${REVIEWER_ID}           , REVIEWER_ID)
     , REVIEWER_NAME          = #DB_OWNER#nvl(${REVIEWER_NAME}         , REVIEWER_NAME)
     , REVIEWER_EMAIL         = #DB_OWNER#nvl(${REVIEWER_EMAIL}        , REVIEWER_EMAIL)
     , REVIEWER_PHONE         = #DB_OWNER#nvl(${REVIEWER_PHONE}        , REVIEWER_PHONE)
     , REVIEWER_COMPANY_CODE  = #DB_OWNER#nvl(${REVIEWER_COMPANY_CODE} , REVIEWER_COMPANY_CODE)
     , REVIEWER_COMPANY_NAME  = #DB_OWNER#nvl(${REVIEWER_COMPANY_NAME} , REVIEWER_COMPANY_NAME)
     , REVIEWER_COMPANY_OWNER = #DB_OWNER#nvl(${REVIEWER_COMPANY_OWNER}, REVIEWER_COMPANY_OWNER)
     , REVIEWER_COMPANY_ADDR  = #DB_OWNER#nvl(${REVIEWER_COMPANY_ADDR} , REVIEWER_COMPANY_ADDR)
     , REVIEW_FLAG            = #DB_OWNER#nvl(${REVIEW_FLAG}           , REVIEW_FLAG)
     , REVIEW_COMMENT         = #DB_OWNER#nvl(${REVIEW_COMMENT}        , REVIEW_COMMENT)
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
   AND SEQ         = ${SEQ}
   AND REVIEWER_ID = ${REVIEWER_ID}


DELETE
  FROM SCTRV
 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
   AND CONT_NO     = ${CONT_NO}
   AND CONT_GL_SEQ = ${CONT_GL_SEQ}
